#include "kstationControllerDeviceState.h"
#include "h8s/h8s.hpp"
#include <array>
#include <cstdio>
#include <cstdlib>
#include <memory>
struct Oracle:H8SEmulator{int rh()const{return lastread;}int wh()const{return lastwrite;}};
struct Event{uint64_t cycle;uint32_t address;uint8_t value;bool write;};
struct OriginalBus:H8SDevice{Oracle& c;std::array<Event,8> event{};unsigned count=0;explicit OriginalBus(Oracle&x):c(x){}uint8_t read(uint32_t a)override{auto v=c.memory[a];event[count++]={c.cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{event[count++]={c.cycles,a,v,true};c.memory[a]=v;}};
struct NativeBus:kstation::ControllerResourceBus{std::array<Event,8> event{};unsigned count=0;bool mapped(uint32_t a)const override{return (a>=0x600000&&a<0x600010)||(a>=0xffff1c&&a<=0xffffff);}uint8_t read(uint32_t a)override{auto v=state_->memory[a];event[count++]={state_->cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{event[count++]={state_->cycles,a,v,true};state_->memory[a]=v;}};
static uint32_t seed=0x918ced73;static uint32_t random32(){seed^=seed<<13;seed^=seed>>17;return seed^=seed<<5;}
int main(){auto a=std::make_unique<Oracle>();auto b=std::make_unique<kstation::ControllerDeviceState>();OriginalBus x(*a);NativeBus y;a->memmap(&x,0x600000,16);a->memmap(&x,0xffff1c,0xe4);b->attachBus(&y);for(unsigned i=0;i<0x1000000;++i)a->memory[i]=b->memory[i]=uint8_t(random32());constexpr uint32_t edges[]={0,1,0x3ffffe,0x3fffff,0x400000,0x600000,0x60000f,0xfffd0f,0xfffd10,0xffff9f,0xffffa0,0xfffff5,0xfffffe,0xffffff,0x1000001};uint64_t transfers=0;for(unsigned n=0;n<30000;++n){if(n==15000)a->cycles=b->cycles=~uint64_t(0)-3;const uint32_t address=n%2?edges[n%(sizeof(edges)/sizeof(*edges))]:random32(),value=random32();unsigned op=n%8;x.count=y.count=0;if(op==0){if(uint8_t(a->read8(int(address)))!=b->read8(address))return 1;}else if(op==1){if(a->read16(int(address))!=b->read16(address))return 2;}else if(op==2){if(a->read32(int(address))!=b->read32(address))return 3;}else if(op==3){a->write8(int8_t(value),int(address));b->write8(address,uint8_t(value));}else if(op==4){a->write16(int16_t(value),int(address));b->write16(address,uint16_t(value));}else if(op==5){a->write32(int32_t(value),int(address));b->write32(address,value);}else if(op==6){int irq=int(value%132)-2;a->interruptMode2=b->interruptMode2=n%16==6;a->interrupt(irq);b->requestInterrupt(irq);}else{unsigned clocks=value%20;a->clockI(clocks);b->clockInternal(clocks);}if(a->cycles!=b->cycles||a->rh()!=b->lastRead||a->wh()!=b->lastWrite||a->pending_irqs!=b->pendingIrqs||a->pending_irqs_high!=b->pendingIrqsHigh||x.count!=y.count){std::fprintf(stderr,"state mismatch n=%u op=%u address=%x\n",n,op,address);return 4;}for(unsigned i=0;i<x.count;++i){const auto&u=x.event[i];const auto&v=y.event[i];if(u.cycle!=v.cycle||u.address!=v.address||u.value!=v.value||u.write!=v.write)return 5;}transfers+=x.count;for(unsigned i=0;i<4;++i)if(a->memory[(address+i)&0xffffff]!=b->memory[(address+i)&0xffffff])return 6;}if(!b->protectImmutable(0x140,0x142)||!b->protectImmutable(0x400140,0x400142)||b->protectImmutable(1,1)||b->protectImmutable(0xffffff,0x1000001))return 7;auto beforeCycles=b->cycles;auto beforeHistory=b->lastWrite;auto beforeValue=b->memory[0x13f];auto beforeCalls=y.count;unsigned guards=0;try{b->write8(0x140,1);}catch(const std::logic_error&){++guards;}try{b->write8(0x400140,1);}catch(const std::logic_error&){++guards;}try{b->writeResource(0x1000141,1);}catch(const std::logic_error&){++guards;}try{b->write16(0x13f,0x1234);}catch(const std::logic_error&){++guards;}try{b->write32(0x13e,0x12345678);}catch(const std::logic_error&){++guards;}uint8_t image[]={1,2,3};try{b->loadMemory(image,3,0x13f);}catch(const std::logic_error&){++guards;}uint8_t valid=b->memory[0x200],invalid=uint8_t(valid^1);if(b->protectImmutableVerified(0x200,0x201,&invalid)||b->isVerifiedImmutable(0x200)||!b->protectImmutableVerified(0x200,0x201,&valid)||!b->isVerifiedImmutable(0x200))return 9;try{b->write8(0x200,uint8_t(valid^1));}catch(const std::logic_error&){++guards;}if(guards!=7||b->cycles!=beforeCycles||b->lastWrite!=beforeHistory||b->memory[0x13f]!=beforeValue||y.count!=beforeCalls)return 8;std::printf("PASS device state: 30000 operations, %llu mapped bus events, exact cycles, histories, wrap, interrupt requests, 7 immutable-write guards and verified bind\n",(unsigned long long)transfers);}
